import type { BiomoleculeQuestion } from "./biomolecules.ts";

type Pack = "cell" | "communication" | "evolution" | "immunity" | "climate";
type Seed = {
  id: string; code: string; page: number; prompt: string;
  options?: string[]; answer?: number; format?: BiomoleculeQuestion["format"];
  data?: BiomoleculeQuestion["data"]; markPoints?: string[]; difficulty?: 1 | 2 | 3;
};

const meta = {
  cell: { file: "2024 H2 Cell - Lecture Notes_Student.docx.pdf", dir: "cell" },
  communication: { file: "Cell Communication.pdf", dir: "communication" },
  evolution: { file: "Biological Evolution.pdf", dir: "evolution" },
  immunity: { file: "Immunity & Infectious Diseases.pdf", dir: "immunity" },
  climate: { file: "Climate Change.pdf", dir: "climate" },
} as const;

const objectives: Record<string, string> = {
  "1(a)":"Cell theory", "1(b)":"Recognising organelles and membrane systems", "1(c)":"Organelle functions", "1(d)":"Typical bacterial cell",
  "3(m)":"Stages of cell signalling", "3(n)":"Second messengers", "3(o)":"Kinases and phosphatases", "3(p)":"Insulin and glucagon signalling",
  "4(a)":"Variation in natural selection", "4(b)":"Environmental selection pressures", "4(c)":"Natural selection and evolution", "4(d)":"Population as the unit of evolution",
  "4(e)":"Preservation of genetic variation", "4(f)":"Descent with modification", "4(g)":"Evidence for evolution", "4(h)":"Species concepts",
  "4(i)":"Classification and evolutionary relationships", "4(j)":"Allopatric and sympatric speciation", "4(k)":"Phylogeny", "4(l)":"Genome sequences and phylogeny",
  "A(a)":"Innate and adaptive immunity", "A(b)":"Cells in primary and secondary responses", "A(c)":"IgG structure and function", "A(d)":"Antibody diversity",
  "A(e)":"Vaccination and disease control", "A(f)":"Benefits and risks of vaccination", "A(g)":"Viral disease", "A(h)":"Tuberculosis", "A(i)":"Antibiotic action",
  "B(a)":"Human causes of climate change", "B(b)":"Environmental effects of climate change", "B(c)":"Plant distribution and adaptation", "B(d)":"Global food supply",
  "B(e)":"Temperature effects on insects", "B(f)":"Aedes aegypti life cycle", "B(g)":"Dengue development and transmission", "B(h)":"Warming and vector-borne disease",
  "B(i)":"Ecosystem stress", "B(j)":"Tropical biodiversity, biomedicines and food diversity",
};

function build(pack: Pack, seeds: Seed[]): BiomoleculeQuestion[] {
  const source = meta[pack];
  return seeds.map((seed) => {
    const format = seed.format ?? "mcq";
    const written = Boolean(seed.markPoints);
    return {
      id: `bio-${pack}-${seed.id}`,
      code: seed.code,
      eyebrow: `${format === "mcq" ? "Verified source" : `${format[0].toUpperCase()}${format.slice(1)}`} · 9744`,
      objective: `${seed.code} ${objectives[seed.code]}`,
      marks: seed.markPoints?.length ?? (seed.difficulty === 3 ? 3 : 2),
      skill: format === "image" ? "Image" : written ? "Exam technique" : format === "mcq" ? "Knowledge" : "Application",
      difficulty: seed.difficulty ?? 2,
      prompt: seed.prompt,
      format,
      options: seed.options,
      answer: seed.answer,
      data: seed.data,
      markPoints: seed.markPoints,
      modelAnswer: seed.markPoints?.join(" "),
      hint: "Use the source evidence, then make each biological link explicit.",
      misconception: objectives[seed.code],
      explanation: written ? "One mark is available for each separate supported point." : `The best answer is ${seed.options?.[seed.answer ?? 0]}.`,
      source: `${source.file} · PDF p.${seed.page}`,
      sourceImage: `/materials/${source.dir}/page-${seed.page}.jpg`,
      sourcePage: seed.page,
    };
  });
}

